INSERT INTO `grievances` (`id`, `grievance_no`, `full_name`, `address`, `email`, `mobile`, `grievance_related_to`, `nature_of_complaint`, `detail_of_complaint`, `district`, `block`, `village`, `project`, `description`, `document`, `filing_on_behalf`, `consent_from_survivor`, `status`, `created_at`, `updated_at`) VALUES
(6, 'GRV-T01EEPXD', 'Jugal Kishor Chaudhary', 'Maya Nivas, Gulab Ghati , Kathgodam Distt Nainital', 'jyotirmai_chaudhury@yahoo.com', '9219509193', 'other', 'Damages to Private Properties', NULL, 'Nainital', NULL, 'Toak Danijala Village Raushil Distt Nainital', NULL, 'Dear Complaint Receiving Officer,\r\n\r\nI am submitting this complaint under the  Accountability Mechanism regarding the proposed Footbridge over Gola River at Danijala, District Nainital, Uttarakhand, India.\r\n\r\nI am a directly affected party, as the approach road of the proposed bridge is mapped on my leased agricultural and residential land without consent, acquisition, or compensation. A status quo order of the Hon’ble High Court of Uttarakhand is already in force, yet construction activity is being pursued, causing serious risk of harm to me and my family.\r\n\r\nThe enclosed complaint (with supporting annexures) demonstrates that:\r\n\r\nThe DPR contains fabricated certificates of consent and inflated beneficiary data.\r\n\r\nTwo existing bridges already serve the same purpose, and a sanctioned motorable road (Kathgodam–Amritpur bypass) will connect Danijala.\r\n\r\nThe project has been misclassified under UDRP and approved without mandatory procedures such as BCR calculation or Land Acquisition Act processes.\r\n\r\nThe project is politically motivated, economically unviable, and designed to benefit only a small group, while imposing disproportionate harm on me.\r\n\r\nI respectfully request that ADB:\r\n\r\nWithhold further disbursement and construction.\r\n\r\nInitiate an independent compliance review and technical/financial audit.\r\n\r\nEnsure recognition of landholder rights and compliance with ADB safeguard policies.\r\n\r\nPlease find attached:\r\n\r\nShort summary complaint (2 pages).\r\n\r\nDetailed grounds of complaint with annexures (RTI replies, DPR extracts, revenue map, High Court order, Google maps).\r\n\r\nI request confirmation of receipt of this complaint.\r\n\r\nSincerely,\r\nJugal Kishor Chaudhary\r\nMaya Nivas, Gulab Ghati, Kathgodam, Distt Nainital', 'grievance_docs/LZkz4OKFbiP7kNIuKmF5haf2cy9KqwN2HWG6rjSP.pdf', 0, 1, 'in-progress', '2025-10-06 02:16:21', '2025-11-10 02:33:03'),
(7, 'GRV-V6ZPP0VJ', 'Mr. Sandeep', 'Haridwar Daluwala', NULL, '7017242565', 'bridges-and-approach-road-pwd', 'Damages to Public Properties', NULL, 'Haridwar', NULL, 'Dhanori', 'Construction of 150M Span Double lane  Motor Bridge over Ratmau River in Daluwala- Lalwala-Dhanauri Motor Road in District Haridwar', 'Crimination ground near to bridge', NULL, 0, 0, 'resolved', '2025-04-07 07:45:26', '2025-07-05 04:33:23'),
(8, 'GRV-WGTT46Q6', 'Jai Shri Ram', '73 C, 4TH FLOOR, Gurudwara Rd, Navjivan Buddh Vihar', 'zoma.engineersndi@gmail.com', '9911800993', 'other', 'Damages to Private Properties', NULL, 'All', NULL, 'Dhanori', NULL, 'प्योरवेज़ इन्फ्रा प्राइवेट लिमिटेड के संबंध में चिंताएँ: ऐसा प्रतीत होता है कि प्योरवेज़ इन्फ्रा प्राइवेट लिमिटेड, अपने कई नाम परिवर्तनों (पूर्व में ग्रोवर इन्फ्रा प्राइवेट लिमिटेड, ग्रोवर इन्फ्रा कॉर्प और वेव्स टेक इंडिया) के बावजूद, आरएफपी की योग्यता मानदंडों को पूरा नहीं कर सकती है। विशेष रूप से:\r\n• इस बात का कोई सत्यापन योग्य प्रमाण नहीं है कि फर्म ने सभी प्रकार की आपदाओं के लिए आपदा जोखिम मूल्यांकन पर अध्ययन किए हैं या पिछले 5 वर्षों में राज्य सरकारों को आवश्यकतानुसार नीतिगत सहायता प्रदान की है।\r\n• फर्म के पास ईएपी/एमडीबी-वित्त पोषित परियोजनाओं, जैसे कि विश्व बैंक द्वारा वित्तपोषित परियोजनाओं, में प्रलेखित अनुभव का अभाव है, जो एक महत्वपूर्ण पात्रता मानदंड है।\r\n• फर्म के परियोजना पोर्टफोलियो में मुख्य रूप से निजी कंपनियों या आपदा जोखिम प्रबंधन, आश्रय डिजाइन, या नीतिगत सहायता के दायरे से अप्रासंगिक परियोजनाओं के लिए उप-परामर्शदाता के रूप में कार्य शामिल हो सकता है, जो आरएफपी आवश्यकताओं को पूरा नहीं करते हैं।\r\n• कई बार नाम बदलने का इतिहास कंपनी की निरंतरता, स्थिरता और कम से कम 5 वर्षों तक उसके अस्तित्व के साथ-साथ इन संस्थाओं (प्योरवेज इन्फ्रा प्राइवेट लिमिटेड, ग्रोवर इन्फ्रा प्राइवेट लिमिटेड, ग्रोवर इन्फ्रा कॉर्प और वेव्स टेक इंडिया) के बीच संबंधों पर सवाल उठाता है।\r\nकार्रवाई का अनुरोध: हम विश्व बैंक से प्योरवेज इन्फ्रा प्राइवेट लिमिटेड की साख का विस्तृत मूल्यांकन करने के लिए एक स्वतंत्र एजेंसी नियुक्त करने का आग्रह करते हैं।\r\npyoravez inphra praivet limited ke sambandh mein chintaen: aisa prateet hota hai ki', NULL, 0, 0, 'resolved', '2025-07-26 04:19:52', '2025-11-10 00:19:13'),
