(65, 8, 80, 'log', 'Grievance Status Updated', 'Status changed from \'pending\' to \'resolved\' by Dr. Mohit Kumar Puniya | Remark: The documents stand verified and validated.', NULL, '2025-11-10 00:19:13', '2025-11-10 00:19:13', NULL),
(66, 6, 104, 'log', 'Grievance Status Updated', 'Status changed from \'Pending\' to \'in-progress\' by Er. Rajesh Pant | Remark: The “Construction of Pedestrian Bridge over the Gaula River at Danijala, Nainital” has been kept on hold.', NULL, '2025-11-10 02:33:03', '2025-11-10 02:33:03', NULL);
