INSERT INTO `package_components` (`id`, `name`, `budget`, `description`, `created_at`, `updated_at`, `deleted_at`, `image`, `page_hin_title`, `page_eng_title`, `hin_content`, `eng_content`) VALUES
(1, 'Enhancing Infrastructure Resilience', 4350000000.00, 'Aims to fortify critical infrastructure against climate and disaster risks by enhancing road infrastructure resilience, improving health service facilities\' readiness, and establishing disaster shelters in vulnerable areas. Measures include reinforcing bridges, implementing bioengineering solutions to mitigate landslides, retrofitting health centers for earthquake and fire safety, and constructing energy-efficient disaster shelters along major routes. These efforts align with the project\'s objective of integrating resi', '2025-08-18 01:42:25', '2025-09-18 00:06:58', NULL, NULL, 'बुनियादी ढांचे के लचीलेपन को बढ़ाना', 'Enhancing Infrastructure Resilience', 'Aims to fortify critical infrastructure against climate and disaster risks by enhancing road infrastructure resilience, improving health service facilities\' readiness, and establishing disaster shelters in vulnerable areas. Measures include reinforcing bridges, implementing bioengineering solutions to mitigate landslides, retrofitting health centers for earthquake and fire safety, and constructing energy-efficient disaster shelters along major routes. These efforts align with the project\'s objective of integrating resi', 'Aims to fortify critical infrastructure against climate and disaster risks by enhancing road infrastructure resilience, improving health service facilities\' readiness, and establishing disaster shelters in vulnerable areas. Measures include reinforcing bridges, implementing bioengineering solutions to mitigate landslides, retrofitting health centers for earthquake and fire safety, and constructing energy-efficient disaster shelters along major routes. These efforts align with the project\'s objective of integrating resi'),
(2, 'Improving Emergency Preparedness & Response', 5050000000.00, 'Enhances disaster prediction, preparedness, and response with a State Emergency Operations Centre, improved\r\nmulti-agency coordination, community DRM campaigns, upgraded hydromet systems for accuracy, timely alerts,\r\nstrengthened State Disaster Response Force with training facilities, equipment, and comprehensive programs.', '2025-08-18 01:42:57', '2025-09-18 00:07:47', NULL, NULL, 'आपातकालीन तैयारी और प्रतिक्रिया में सुधार', 'Improving Emergency Preparedness & Response', 'राज्य आपातकालीन संचालन केंद्र, बेहतर\r\nबहु-एजेंसी समन्वय, सामुदायिक डीआरएम अभियान, सटीकता के लिए उन्नत हाइड्रोमेट सिस्टम, समय पर अलर्ट,\r\nप्रशिक्षण सुविधाओं, उपकरणों और व्यापक कार्यक्रमों के साथ राज्य आपदा प्रतिक्रिया बल को मजबूत करके आपदा पूर्वानुमान, तैयारी और प्रतिक्रिया को बेहतर बनाया गया है।', 'Enhances disaster prediction, preparedness, and response with a State Emergency Operations Centre, improved\r\nmulti-agency coordination, community DRM campaigns, upgraded hydromet systems for accuracy, timely alerts,\r\nstrengthened State Disaster Response Force with training facilities, equipment, and comprehensive programs.'),
(3, 'Preventing & Managing Forest & General Fires', 3730000000.00, 'Enhancing fire prevention and management capacities includes fire risk assessments, state-level fire management plans, advanced firefighting technologies, and community-based initiatives. Efforts focus on early detection, policy assessments, equipment procurement, and incentive-based programs for sustainable forest management. These measures mitigate fire risks, promote biodiversity, and ensure long-term sustainability.', '2025-08-18 01:43:20', '2025-09-18 00:08:46', NULL, NULL, 'वन एवं सामान्य आग की रोकथाम एवं प्रबंधन', 'Preventing & Managing Forest & General Fires', 'अग्नि निवारण और प्रबंधन क्षमताओं को बढ़ाने में अग्नि जोखिम आकलन, राज्य-स्तरीय अग्नि प्रबंधन योजनाएँ, उन्नत अग्निशमन प्रौद्योगिकियाँ और समुदाय-आधारित पहल शामिल हैं। प्रयास शीघ्र पहचान, नीतिगत आकलन, उपकरण खरीद और स्थायी वन प्रबंधन के लिए प्रोत्साहन-आधारित कार्यक्रमों पर केंद्रित हैं। ये उपाय अग्नि जोखिमों को कम करते हैं, जैव विविधता को बढ़ावा देते हैं और दीर्घकालिक स्थिरता सुनिश्चित करते हैं।', 'Enhancing fire prevention and management capacities includes fire risk assessments, state-level fire management plans, advanced firefighting technologies, and community-based initiatives. Efforts focus on early detection, policy assessments, equipment procurement, and incentive-based programs for sustainable forest management. These measures mitigate fire risks, promote biodiversity, and ensure long-term sustainability.'),
(4, 'Project Management', 1670000000.00, 'Facilitates project management and knowledge sharing through financial management, procurement, environmental and social management, communication, monitoring, evaluation, and stakeholder engagement. Establishes Lighthouse Uttarakhand for sharing project lessons, capacity building, and knowledge exchange among Indian states.', '2025-08-18 01:43:38', '2025-09-18 00:09:25', NULL, NULL, 'परियोजना प्रबंधन', 'Project Management', 'वित्तीय प्रबंधन, खरीद, पर्यावरण एवं सामाजिक प्रबंधन, संचार, निगरानी, ​​मूल्यांकन और हितधारक सहभागिता के माध्यम से परियोजना प्रबंधन और ज्ञान साझाकरण को सुगम बनाता है। भारतीय राज्यों के बीच परियोजना संबंधी जानकारी साझा करने, क्षमता निर्माण और ज्ञान के आदान-प्रदान के लिए लाइटहाउस उत्तराखंड की स्थापना करता है।', 'Facilitates project management and knowledge sharing through financial management, procurement, environmental and social management, communication, monitoring, evaluation, and stakeholder engagement. Establishes Lighthouse Uttarakhand for sharing project lessons, capacity building, and knowledge exchange among Indian states.');
