INSERT INTO `pages` (`id`, `title`, `title_hi`, `slug`, `body_eng`, `body_hindi`, `meta_title`, `meta_description`, `meta_keywords`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'About U-PREPARE', 'हमारे बारे में', 'about-u-prepare', '<p style=\"text-align: justify;\">Uttarakhand Disaster Recovery Project (UDRP) and Additional Financing (AF) have been implemented by the Government of Uttarakhand since 2013, with funding from the World Bank. This project focused on various aspects such as the restoration of housing and rural connectivity, riverbanks protection works, enhancing community resilience, and strengthening the state\'s emergency response capabilities.</p>\r\n<p style=\"text-align: justify;\"><strong>Uttarakhand Disaster Preparedness and Resilience Project (U-PREPARE) </strong>constitutes a large multi-sectoral engagement on risk and vulnerability reduction with assistance for reconstructing damaged resilient infrastructure, restoring connectivity, enhancing medical health facilities, strengthening SDRF &amp; Fire services, early warning &amp; response system, establishing Hydro meteorological network, strengthening &amp; upgradation of State command and Control Centre of Forest department, upgradation of existing &amp; construction of new Forest Crew Stations and improving technical support for managing future disaster risks. The Project design has incorporated lessons learned from previous national and global post-disaster recovery projects to ensure that the recovery is targeted, eective and is built back &ldquo;smarter&rdquo; in order to build resilience of local communities to future disasters.</p>\r\n<p style=\"text-align: justify;\">The primary beneINSERT INTO `pages` (`id`, `title`, `title_hi`, `slug`, `body_eng`, `body_hindi`, `meta_title`, `meta_description`, `meta_keywords`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(19, 'Reading Material', 'Reading Material', 'reading-material', '<ul>\r\n<li><a href=\"../../../storage/financial_progress/QyEDSrSIzYphfgcVL045LaRvmtaKwnH674VYbKPk.pdf\" target=\"_blank\" rel=\"noopener\">Reading View&nbsp;</a></li>\r\n</ul>', '<ul>\r\n<li><a href=\"../../../storage/financial_progress/QyEDSrSIzYphfgcVL045LaRvmtaKwnH674VYbKPk.pdf\" target=\"_blank\" rel=\"noopener\">Reading View&nbsp;</a></li>\r\n</ul>', 'Reading Material', NULL, NULL, 1, '2025-09-19 04:16:06', '2025-09-19 04:18:26', NULL),
