INSERT INTO `slides` (`id`, `img`, `head`, `subh`, `btn_text`, `link`, `order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'slides/Re0uFNLkIqWddW3jiWELMuk07B3sHTQguTVhntvo.webp', 'Resilient Uttarakhand: Safeguarding Lives and Landscapes', 'Nestled amidst the majestic Himalayas, the Uttarakhand Disaster Management Authority stands vigilant, committed to protecting our communities and preserving our natural heritage', NULL, NULL, 1, 0, '2025-08-22 23:22:10', '2025-09-18 07:17:31'),
(2, 'slides/Uv3QQlYSZ2cs7BHiPYIMJMsaSd3L0Dx3aumUjMEJ.webp', 'Building Resilient Infrastructure', 'Fortifying foundations for a sustainable tomorrow. Strengthening structures and systems to withstand the test of time and nature.', NULL, NULL, 2, 1, '2025-08-22 23:22:10', '2025-08-22 23:28:57'),
(3, 'slides/rLT9rBornUJPpiRiN9MWzUt6NBVBlwHyvpOekCFK.webp', 'Elevating Emergency Preparedness and Response', 'Ready, resilient, responsive. Equipping communities with the tools and knowledge to face emergencies head-on, ensuring safety and swift action.', NULL, NULL, 3, 1, '2025-08-22 23:22:10', '2025-08-22 23:29:07'),
(4, 'slides/NRsfkuhlsxUxBJdm3v8jkTo94qWhHPpwxUn4jm9C.webp', 'Safeguarding Against Forest and General Fires', 'Guardians of green, protectors of progress. Combating fire hazards through vigilant prevention and effective management, safeguarding our natural and built environments.', NULL, NULL, 4, 1, '2025-08-22 23:22:10', '2025-08-22 23:29:14'),
